Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.io.*;
import java.util.*;

public class Main {
    static PrintWriter out;
    static double EPS = 1e-9;
    static int INF = (int) 1e9;
    static long LINF = (long) 1e18;
    static int MOD = (int) 1e9 + 7;
    static double PI = Math.acos(-1);

    static int go(long n) {
        if (n == 0) return 0;
        long k = 1;
        int cnt = 1;
        while (k * 10 + 1 < n) {
            k = k * 10 + 1;
            cnt++;
        }
        return (int) Math.min(go(n % k) + n / k * cnt,
                go((k * 10 + 1 - n) % k) + (cnt + 1) + (k * 10 + 1 - n) / k * cnt);
    }

    static void solve() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long n = Long.parseLong(br.readLine().trim());
        out.println(go(n));
    }

    public static void main(String[] args) throws IOException {
        out = new PrintWriter(System.out);
        solve();
        out.close();
    }
}
